msg.payload = {
    author: "safonchik",
    lab: "lab2",
    time: new Date().toISOString()
};
msg.headers = { "Content-Type": "application/json" };
return msg;

const category = msg.req.params.category;
const limit = parseInt(msg.req.query.limit) || 10;

if (limit < 0 || limit > 100) {
    msg.statusCode = 400;
    msg.payload = {
        error: "Bad Request",
        message: "limit должен быть от 0 до 100",
        received: limit
    };
    msg.headers = { "Content-Type": "application/json" };
    return msg;
}

const allowed = ["books", "movies", "games"];
if (!allowed.includes(category)) {
    msg.statusCode = 404;
    msg.payload = {
        error: "Not Found",
        message: `Категория '${category}' не существует`,
        allowed: allowed
    };
    msg.headers = { "Content-Type": "application/json" };
    return msg;
}

const items = [];
for (let i = 1; i <= limit; i++) {
    items.push({ id: i, name: `${category}-${i}`, author: "safonchik" });
}

msg.statusCode = 200;
msg.payload = { category: category, count: items.length, items: items };
msg.headers = { "Content-Type": "application/json" };
return msg;
